Lemma XS_system_cat' : forall m, XStatics m ->
  rw_cells usegs m 0x84b98 [C8 (Z_to_bv 64 0x7e528); C8 (Z_to_bv 64 0xb2ab117a257edfd1)].
Proof.
  intros m XS. destruct XS as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & H0 & _). exact H0.
Qed.

Lemma le8_zero_split' : le8 (Z_to_bv 64 0) = le4 (Z_to_bv 64 0) ++ le4 (Z_to_bv 64 0).
Proof. vm_compute. reflexivity. Qed.
Lemma rw_cells_C8zero_split' : forall m A pre post,
  rw_cells usegs m A (pre ++ C8 (Z_to_bv 64 0) :: post) ->
  rw_cells usegs m A (pre ++ C4 (Z_to_bv 64 0) :: C4 (Z_to_bv 64 0) :: post).
Proof.
  intros m A pre post RC. pose proof RC as [[WF _] _]. apply cells_wf_app in WF. destruct WF as [W1 [_ W3]].
  eapply rw_cells_recells; [exact RC| | |].
  - apply cells_wf_app. split; [exact W1|]. cbn. split; [exact I|]. split; [exact I|]. exact W3.
  - rewrite !cells_bytes_app. cbn [cells_bytes cbytes]. rewrite le8_zero_split', <- app_assoc. reflexivity.
  - rewrite !cells_size_app. reflexivity.
Qed.

