Definition CEM_CTOR_STACK : Z := 144 + MUTEX_INIT_STACK.

Definition cem_ctor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (M en spin lo : Z) (junk : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (M, M + 56)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' M [CB 8 (firstn 8 junk)]
    /\ PMutex m' (M + 8) 0
    /\ (exists j3, rw_cells usegs m' (M + 48) [C4 (wz spin); CB 1 [b8 en]; CB 3 j3])
    /\ CanaryReads m' /\ XStatics m'.

Definition cem_ctor_stmt : Prop :=
  forall (M en spin lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (junk : list byte),
  rw_cells usegs m M [CB 56 junk] -> M mod 8 = 0 -> 0 < M ->
  M + 56 <= lo -> (M + 56 <= 0x10000 \/ 0xb8000 <= M) ->
  (en = 0 \/ en = 1) -> 0 <= spin < 2^31 ->
  XStatics m -> CanaryReads m ->
  stk usegs m lo (bv_unsigned sp) -> lo + CEM_CTOR_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (cem_ctor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc M en spin lo junk m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz M) (wz en) (wz spin) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CEM_CTOR) fc None m (seg_rom usegs)).
