(* [comment removed for export] *)
(* [comment removed for export] *)
Definition POSIX_EVENT_CTOR_STACK : Z := 128 + COND_INIT_STACK.

Definition posix_event_ctor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (C lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (C, C + 56)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ PCond m' C CLOCK_MONOTONIC
    /\ rw_cells usegs m' (C + 48) [C8 (wz 0)]
    /\ CanaryReads m' /\ XStatics m'.

Definition posix_event_ctor_stmt : Prop :=
  forall (C lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (junk : list byte),
  rw_cells usegs m C [CB 56 junk] -> C mod 8 = 0 -> 0 < C ->
  C + 56 <= lo -> (C + 56 <= 0x10000 \/ 0xb8000 <= C) ->
  XStatics m -> CanaryReads m ->
  stk usegs m lo (bv_unsigned sp) -> lo + POSIX_EVENT_CTOR_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
